/** Shared constants for Project Runtime. */

/** Marker line inside every generated file; the basis of drift detection. */
export const GENERATED_HEADER_MARKER = "GENERATED BY RUNTIME — DO NOT EDIT.";

/** `sync` warns when a generated file exceeds this size (import mode is planned for v1.1). */
export const SIZE_WARN_BYTES = 20 * 1024;

/** Per-line allowlist marker for secret scanning. A line containing it is skipped. */
export const ALLOW_SECRET_MARKER = "runtime:allow-secret";

/** Drift manifest location, relative to the repo root. Committed to git. */
export const MANIFEST_REL_PATH = ".runtime/manifest.json";

/** Cap for context/rules files inlined into the definition. */
export const MAX_SOURCE_FILE_BYTES = 128 * 1024;

/** Cap for files scanned by `runtime check`; larger files are skipped with a warning. */
export const CHECK_MAX_FILE_BYTES = 1024 * 1024;

/**
 * Cooperative per-check time budget for `runtime check` (M3): a static check
 * that exceeds it is `skipped` — never a hang, never a pass. Residual risk:
 * a single line that backtracks catastrophically inside one regex.test call
 * cannot be interrupted without worker threads (unsupported in Node SEA
 * builds); the 1 MB per-file input cap bounds that work.
 */
export const CHECK_TIME_BUDGET_MS = 1_000;
